#!/usr/bin/env python3
from pathlib import Path
import argparse,subprocess
p=argparse.ArgumentParser();p.add_argument('--scratch',type=Path,required=True);a=p.parse_args();a.scratch.mkdir(parents=True,exist_ok=True)
r=Path(__file__).resolve().parents[1];s=(r/'tools/winpe/mt8167-peripheral-update.c').read_text();fn=s[s.index('static DWORD selected_runtime('):s.index('static DWORD installed_gpu_extras(')]
shim='''#include <assert.h>\ntypedef unsigned DWORD;typedef void* HDEVINFO;typedef struct{int x;} SP_DEVINFO_DATA;\n#define ERROR_NOT_READY 21\n#define ERROR_NOT_FOUND 1168\nstatic DWORD identity,inf,selected_inf_locator_unverified,calls;\nstatic DWORD selected_identity(unsigned i,HDEVINFO h,SP_DEVINFO_DATA*d,int c){(void)i;(void)h;(void)d;assert(c==1);return identity;}\nstatic DWORD installed_inf(unsigned i,HDEVINFO h,SP_DEVINFO_DATA*d,int c){(void)i;(void)h;(void)d;assert(c==1);calls++;return inf;}\n'''
main='''int main(void){DWORD e,errors[]={2,5,13,23,1306,1790};unsigned i;SP_DEVINFO_DATA d;identity=0;inf=0;assert(selected_runtime(10,0,&d,&e)==0&&e==0);inf=1168;selected_inf_locator_unverified=1;assert(selected_runtime(10,0,&d,&e)==0&&e==1168);selected_inf_locator_unverified=0;assert(selected_runtime(10,0,&d,&e)==1168);for(i=0;i<sizeof(errors)/sizeof(errors[0]);i++){inf=errors[i];selected_inf_locator_unverified=1;assert(selected_runtime(10,0,&d,&e)==errors[i]);}identity=1306;calls=0;assert(selected_runtime(10,0,&d,&e)==1306&&!calls&&e==21);return 0;}'''
f=a.scratch/'selected-inf-gate.c';f.write_text(shim+fn+main);exe=a.scratch/'selected-inf-gate';subprocess.run(['cc','-std=c11','-Wall','-Wextra','-Werror','-fsanitize=address,undefined',str(f),'-o',str(exe)],check=True);subprocess.run([str(exe)],check=True);print('ONLY_LOCATOR_1168_OPTIONAL_IDENTITY_HASH_TYPE_ACCESS_ERRORS_STILL_FATAL_PASS')
